478→            .pipe(
479→                take(1),
480→                map((channels) => getChannelItemByNumber(channels, channelNumber))
481→            )
482→            .subscribe((channel) => {
483→                if (channel) {
484→                    this.store.dispatch(
485→                        ChannelActions.setActiveChannel({ channel })
486→                    );
487→                }
488→            });
489→    }
490→
491→    /**
492→     * Clear channel number input and hide overlay
493→     */
494→    clearChannelNumberInput(): void {
495→        this.channelNumberInput = '';
496→        this.showChannelNumberOverlay = false;
497→        if (this.channelNumberTimeout) {
498→            clearTimeout(this.channelNumberTimeout);
499→            this.channelNumberTimeout = undefined;
500→        }
501→    }
502→
503→    /**
504→     * Check if the user is currently typing in an input or textarea field
505→     * @param event Keyboard event
506→     * @returns true if the event target is an input or textarea element
507→     */
508→    private isTypingInInput(event: Event): boolean {
509→        const target = event.target;
510→        return (
511→            target instanceof HTMLInputElement ||
512→            target instanceof HTMLTextAreaElement
513→        );
514→    }
515→
516→    private handleRemoteControlCommand(command: {
517→        type:
518→            | 'channel-select-number'
519→            | 'volume-up'
520→            | 'volume-down'
521→            | 'volume-toggle-mute';
522→        number?: number;
523→    }): void {
524→        if (command.type === 'channel-select-number' && command.number) {
525→            this.switchToChannelByNumber(command.number);
526→            return;
527→        }
528→
529→        if (command.type === 'volume-up') {
530→            this.setVolume(this.volume + 0.1);
531→        } else if (command.type === 'volume-down') {
532→            this.setVolume(this.volume - 0.1);
533→        } else if (command.type === 'volume-toggle-mute') {
534→            if (this.volume === 0) {
535→                this.setVolume(this.lastKnownVolume || 1);
536→            } else {
537→                this.lastKnownVolume = this.volume;
538→                this.setVolume(0);
539→            }
540→        }
541→    }
542→
543→    private setVolume(next: number): void {
544→        const clamped = Math.max(0, Math.min(1, Number(next.toFixed(2))));
545→        this.volume = clamped;
546→        if (clamped > 0) {
547→            this.lastKnownVolume = clamped;
548→        }
549→        localStorage.setItem('volume', String(clamped));
550→
551→        if (window.electron?.updateRemoteControlStatus) {
552→            window.electron.updateRemoteControlStatus({
553→                portal: 'm3u',
554→                isLiveView: true,
555→                supportsVolume: true,
556→                volume: this.volume,
557→                muted: this.volume === 0,
558→            });
559→        }
560→    }
561→}
