 28→export class HtmlVideoPlayerComponent implements OnInit, OnChanges, OnDestroy {
 29→    /** Channel to play  */
 30→    @Input() channel!: Channel;
 31→    @Input() volume = 1;
 32→    @Input() startTime = 0;
 33→    @Output() timeUpdate = new EventEmitter<{
 34→        currentTime: number;
 35→        duration: number;
 36→    }>();
 37→
 38→    private readonly dataService = inject(DataService);
 39→
 40→    /** Video player DOM element */
 41→    @ViewChild('videoPlayer', { static: true })
 42→    videoPlayer!: ElementRef<HTMLVideoElement>;
 43→
 44→    /** HLS object */
 45→    hls!: Hls;
 46→
 47→    /** Captions/subtitles indicator */
 48→    @Input() showCaptions!: boolean;
 49→
 50→    ngOnInit() {
 51→        this.videoPlayer.nativeElement.addEventListener('volumechange', () => {
 52→            this.onVolumeChange();
 53→        });
 54→
 55→        this.videoPlayer.nativeElement.addEventListener('loadedmetadata', () => {
 56→            if (this.startTime > 0) {
 57→                this.videoPlayer.nativeElement.currentTime = this.startTime;
 58→            }
 59→        });
 60→
 61→        this.videoPlayer.nativeElement.addEventListener('timeupdate', () => {
 62→            this.timeUpdate.emit({
 63→                currentTime: this.videoPlayer.nativeElement.currentTime,
 64→                duration: this.videoPlayer.nativeElement.duration,
 65→            });
 66→        });
 67→    }
 68→
 69→    /**
 70→     * Listen for component input changes
 71→     * @param changes component changes
 72→     */
 73→    ngOnChanges(changes: SimpleChanges): void {
 74→        if (changes['channel'] && changes['channel'].currentValue) {
 75→            this.playChannel(changes['channel'].currentValue);
 76→        }
 77→        if (changes['volume']?.currentValue !== undefined) {
 78→            console.log(
 79→                'Setting HTML5 player volume to:',
 80→                changes['volume'].currentValue
 81→            );
 82→            this.videoPlayer.nativeElement.volume =
 83→                changes['volume'].currentValue;
 84→        }
 85→    }
 86→
 87→    /**
 88→     * Starts to play the given channel
 89→     * @param channel given channel object
 90→     */
 91→    playChannel(channel: Channel): void {
 92→        if (this.hls) this.hls.destroy();
 93→        if (channel.url) {
 94→            const url = channel.url + (channel.epgParams ?? '');
 95→            const extension = getExtensionFromUrl(channel.url);
 96→
 97→            // Set user agent if specified on channel
 98→            if (channel.http?.['user-agent']) {
 99→                window.electron?.setUserAgent(
100→                    channel.http['user-agent'],
101→                    channel.http.referrer
102→                );
103→            }
104→
105→            if (
106→                extension !== 'mp4' &&
107→                extension !== 'mpv' &&
108→                Hls &&
109→                Hls.isSupported()
110→            ) {
111→                console.log('... switching channel to ', channel.name, url);
112→                this.hls = new Hls();
113→                this.hls.attachMedia(this.videoPlayer.nativeElement);
114→                this.hls.loadSource(url);
115→                this.handlePlayOperation();
116→            } else {
117→                console.log('Using native video player...');
118→                this.addSourceToVideo(
119→                    this.videoPlayer.nativeElement,
120→                    url,
121→                    'video/mp4'
122→                );
123→                this.videoPlayer.nativeElement.play();
124→            }
125→        }
126→    }
127→
128→    addSourceToVideo(element: HTMLVideoElement, url: string, type: string) {
129→        const source = document.createElement('source');
130→        source.src = url;
131→        source.type = type;
132→        element.appendChild(source);
133→    }
134→
135→    /**
136→     * Disables text based captions based on the global settings
137→     */
138→    disableCaptions(): void {
139→        for (
140→            let i = 0;
141→            i < this.videoPlayer.nativeElement.textTracks.length;
142→            i++
143→        ) {
144→            this.videoPlayer.nativeElement.textTracks[i].mode = 'hidden';
145→        }
146→    }
147→
148→    /**
149→     * Handles promise based play operation
150→     */
151→    handlePlayOperation(): void {
152→        const playPromise = this.videoPlayer.nativeElement.play();
153→
154→        if (playPromise !== undefined) {
155→            playPromise
156→                .then(() => {
157→                    // Automatic playback started!
158→                    if (!this.showCaptions) {
159→                        this.disableCaptions();
160→                    }
161→                })
162→                .catch(() => {
163→                    // Do nothing
164→                });
165→        }
166→    }
167→
168→    /**
169→     * Save volume when user changes it
170→     */
171→    onVolumeChange(): void {
172→        const currentVolume = this.videoPlayer.nativeElement.volume;
173→        console.log('Volume changed to:', currentVolume);
174→        localStorage.setItem('volume', currentVolume.toString());
175→    }
176→
177→    /**
178→     * Destroy hls instance on component destroy and clean up event listener
179→     */
180→    ngOnDestroy(): void {
181→        this.videoPlayer.nativeElement.removeEventListener(
182→            'volumechange',
183→            this.onVolumeChange
184→        );
185→        if (this.hls) {
186→            this.hls.destroy();
187→        }
188→    }
189→}
