154→            panelClass: 'global-search-overlay',
155→            data: { isGlobalSearch: true },
156→        });
157→    }
158→
159→    openGlobalRecent(): void {
160→        this.dialog.open(GlobalRecentlyViewedComponent, {
161→            width: '100%',
162→            height: '100%',
163→            maxWidth: '100%',
164→            panelClass: 'global-search-overlay',
165→            data: { isGlobal: true },
166→            hasBackdrop: true,
167→            disableClose: false,
168→        });
169→    }
170→
171→    /**
172→     * Fetches EPG data only for URLs that have stale or missing data.
173→     * Data is considered fresh if updated within the last 12 hours.
174→     */
175→    private async fetchStaleEpgData(urls: string[]): Promise<void> {
176→        try {
177→            const result = await window.electron.checkEpgFreshness(urls, 12);
178→
179→            if (result.freshUrls.length > 0) {
180→                console.log(
181→                    `EPG: ${result.freshUrls.length} source(s) already fresh, skipping fetch`
182→                );
183→                // Show snackbar if all EPG sources are fresh (no stale URLs)
184→                if (result.staleUrls.length === 0) {
185→                    this.snackBar.open(
186→                        this.translate.instant('EPG.UP_TO_DATE'),
187→                        this.translate.instant('CLOSE'),
188→                        { duration: 3000 }
189→                    );
190→                }
191→            }
192→
193→            if (result.staleUrls.length > 0) {
194→                console.log(
195→                    `EPG: Fetching ${result.staleUrls.length} stale source(s)`
196→                );
197→                this.epgService.fetchEpg(result.staleUrls);
198→            }
199→        } catch (error) {
200→            console.error('Error checking EPG freshness, fetching all:', error);
201→            // Fallback: fetch all URLs if freshness check fails
202→            this.epgService.fetchEpg(urls);
203→        }
204→    }
205→
206→    /**
207→     * Triggers auto-update for playlists that have autoRefresh enabled
208→     */
209→    private triggerAutoUpdatePlaylists(): void {
210→        // Wait for playlists to be loaded successfully
211→        this.actions$
212→            .pipe(
213→                ofType(PlaylistActions.loadPlaylistsSuccess),
214→                take(1) // Only trigger once on app startup
215→            )
216→            .subscribe(() => {
217→                // Get all playlists from store
218→                this.store
219→                    .select(selectAllPlaylistsMeta)
220→                    .pipe(
221→                        take(1),
222→                        filter((playlists) => playlists.length > 0)
223→                    )
224→                    .subscribe((playlists) => {
225→                        // Filter playlists with autoRefresh enabled
226→                        const playlistsToUpdate = playlists.filter(
227→                            (playlist) => playlist.autoRefresh === true
228→                        );
229→
230→                        // Trigger auto-update if there are playlists to update
231→                        if (playlistsToUpdate.length > 0) {
232→                            console.log(
233→                                `Auto-updating ${playlistsToUpdate.length} playlist(s) on startup`
234→                            );
235→                            this.dataService.sendIpcEvent(
236→                                AUTO_UPDATE_PLAYLISTS,
237→                                playlistsToUpdate
238→                            );
239→                        }
240→                    });
241→            });
242→    }
243→}
