 45→type LiveChannelSortMode = 'server' | 'name-asc' | 'name-desc';
 46→const LIVE_CHANNEL_SORT_STORAGE_KEY = 'xtream-live-channel-sort-mode';
 47→
 48→@Component({
 49→    selector: 'app-live-stream-layout',
 50→    templateUrl: './live-stream-layout.component.html',
 51→    styleUrls: ['./live-stream-layout.component.scss', '../sidebar.scss'],
