 72→export class LiveStreamLayoutComponent implements OnInit, OnDestroy {
 73→    private readonly favoritesService = inject(FavoritesService);
 74→    private readonly xtreamStore = inject(XtreamStore);
 75→    private readonly settingsStore = inject(SettingsStore);
 76→    private readonly dialog = inject(MatDialog);
 77→    private readonly route = inject(ActivatedRoute);
 78→
 79→    readonly categories = this.xtreamStore.getCategoriesBySelectedType;
 80→    readonly categoryItemCounts = this.xtreamStore.getCategoryItemCounts;
 81→    readonly currentPlaylist = this.xtreamStore.currentPlaylist;
 82→    readonly epgItems = this.xtreamStore.epgItems;
 83→    readonly selectedCategoryId = this.xtreamStore.selectedCategoryId;
 84→    readonly liveChannelSortMode = signal<LiveChannelSortMode>('server');
 85→    readonly liveChannelSortLabel = computed(() => {
 86→        const mode = this.liveChannelSortMode();
 87→        if (mode === 'name-asc') return 'Name A-Z';
 88→        if (mode === 'name-desc') return 'Name Z-A';
 89→        return 'Server Order';
 90→    });
 91→
 92→    readonly selectedCategoryInfo = computed(() => {
 93→        const categoryId = this.selectedCategoryId();
 94→        if (!categoryId) return null;
 95→
 96→        const categories = this.categories();
 97→        const category = categories?.find(
 98→            (c: any) => (c.category_id ?? c.id) === categoryId
 99→        );
100→        const count = this.categoryItemCounts()?.get(categoryId) ?? 0;
101→
102→        return {
103→            name: category?.category_name ?? category?.name ?? 'Channels',
104→            count,
105→        };
106→    });
107→
108→    private readonly injector = inject(Injector);
109→    private readonly categoryView = viewChild(CategoryViewComponent, {
110→        read: ElementRef,
111→    });
112→    private categoryScrollTop = 0;
113→    private unsubscribeRemoteChannelChange?: () => void;
114→    private unsubscribeRemoteCommand?: () => void;
115→
116→    readonly player = this.settingsStore.player;
117→    streamUrl: string;
118→    favorites = new Map<number, boolean>();
119→
120→    constructor() {
121→        effect(() => {
122→            if (!window.electron?.updateRemoteControlStatus) {
123→                return;
124→            }
125→
126→            const selectedContentType = this.xtreamStore.selectedContentType();
127→            const selectedItem = this.xtreamStore.selectedItem();
128→            const channels = this.xtreamStore.selectItemsFromSelectedCategory() as any[];
129→            const epgItems = this.xtreamStore.epgItems();
130→
131→            if (selectedContentType !== 'live' || !selectedItem?.xtream_id) {
132→                window.electron.updateRemoteControlStatus({
133→                    portal: 'xtream',
134→                    isLiveView: false,
135→                    supportsVolume: false,
136→                });
137→                return;
138→            }
139→
140→            const currentIndex = channels.findIndex(
141→                (item) =>
142→                    Number(item.xtream_id) === Number(selectedItem.xtream_id)
143→            );
144→            const currentProgram = epgItems?.[0];
145→
146→            window.electron.updateRemoteControlStatus({
147→                portal: 'xtream',
148→                isLiveView: true,
149→                channelName: selectedItem.title ?? selectedItem.name,
150→                channelNumber: currentIndex >= 0 ? currentIndex + 1 : undefined,
151→                epgTitle: currentProgram?.title,
152→                epgStart: (currentProgram as any)?.start,
153→                epgEnd: (currentProgram as any)?.end,
154→                supportsVolume: false,
155→            });
156→        });
157→    }
158→
159→    ngOnInit() {
160→        if (window.electron?.onChannelChange) {
161→            const unsubscribe = window.electron.onChannelChange((data: {
162→                direction: 'up' | 'down';
163→            }) => {
164→                this.handleRemoteChannelChange(data.direction);
165→            });
166→            if (typeof unsubscribe === 'function') {
167→                this.unsubscribeRemoteChannelChange = unsubscribe;
168→            }
169→        }
170→        if (window.electron?.onRemoteControlCommand) {
171→            const unsubscribe = window.electron.onRemoteControlCommand(
172→                (command) => {
173→                    this.handleRemoteControlCommand(command);
174→                }
175→            );
176→            if (typeof unsubscribe === 'function') {
177→                this.unsubscribeRemoteCommand = unsubscribe;
178→            }
179→        }
180→
181→        const savedSortMode = localStorage.getItem(
182→            LIVE_CHANNEL_SORT_STORAGE_KEY
183→        );
184→        if (
185→            savedSortMode === 'server' ||
186→            savedSortMode === 'name-asc' ||
187→            savedSortMode === 'name-desc'
188→        ) {
189→            this.liveChannelSortMode.set(savedSortMode);
190→        }
191→
192→        const playlist = this.xtreamStore.currentPlaylist();
193→        if (playlist) {
194→            this.favoritesService
195→                .getFavorites(playlist.id)
196→                .subscribe((favorites) => {
197→                    // Map using content.id instead of xtream_id
198→                    favorites.forEach((fav: any) => {
199→                        this.favorites.set(fav.xtream_id, true);
200→                    });
201→                });
202→        }
203→
204→        const categoryId = this.route.firstChild?.snapshot.params['categoryId'];
205→        if (categoryId)
206→            this.xtreamStore.setSelectedCategory(Number(categoryId));
207→    }
208→
209→    playLive(item: any) {
210→        const streamUrl = this.xtreamStore.constructStreamUrl(item);
211→        this.streamUrl = streamUrl;
212→        const isEmbeddedPlayer =
213→            this.player() === 'videojs' ||
214→            this.player() === 'html5' ||
215→            this.player() === 'artplayer';
216→        if (isEmbeddedPlayer) {
217→            return;
218→        }
219→        this.xtreamStore.openPlayer(streamUrl, item.title, item.poster_url);
220→    }
221→
222→    selectCategory(category: XtreamCategory) {
223→        const el = this.categoryView()?.nativeElement;
224→        if (el) {
225→            this.categoryScrollTop = el.scrollTop;
226→        }
227→        const categoryId = (category as any).category_id ?? category.id;
228→        this.xtreamStore.setSelectedCategory(categoryId);
229→    }
230→
231→    backToCategories() {
232→        this.xtreamStore.setSelectedCategory(null);
233→        afterNextRender(
234→            () => {
235→                const el = this.categoryView()?.nativeElement;
236→                if (el) {
237→                    el.scrollTop = this.categoryScrollTop;
238→                }
239→            },
240→            { injector: this.injector }
241→        );
242→    }
243→
244→    openCategoryManagement(): void {
245→        const playlistId = this.route.parent?.snapshot.params['id'];
246→        const contentType = this.xtreamStore.selectedContentType();
247→
248→        const dialogRef = this.dialog.open<
249→            CategoryManagementDialogComponent,
250→            CategoryManagementDialogData,
251→            boolean
252→        >(CategoryManagementDialogComponent, {
253→            data: {
254→                playlistId,
255→                contentType,
256→                itemCounts: this.categoryItemCounts(),
257→            },
258→            width: '500px',
259→            maxHeight: '80vh',
260→        });
261→
262→        dialogRef.afterClosed().subscribe((result) => {
263→            if (result) {
264→                this.xtreamStore.reloadCategories();
265→            }
266→        });
267→    }
268→
269→    setLiveChannelSortMode(mode: LiveChannelSortMode): void {
270→        this.liveChannelSortMode.set(mode);
271→        localStorage.setItem(LIVE_CHANNEL_SORT_STORAGE_KEY, mode);
272→    }
273→
274→    ngOnDestroy(): void {
275→        this.unsubscribeRemoteChannelChange?.();
276→        this.unsubscribeRemoteCommand?.();
277→    }
278→
279→    private handleRemoteChannelChange(direction: 'up' | 'down'): void {
280→        const activeItem = this.xtreamStore.selectedItem();
281→        if (!activeItem?.xtream_id) {
282→            return;
283→        }
284→
285→        const channels = this.xtreamStore.selectItemsFromSelectedCategory() as any[];
286→        const nextItem = getAdjacentChannelItem(
287→            channels,
288→            activeItem.xtream_id,
289→            direction,
290→            (item) => item.xtream_id
291→        );
292→
293→        if (!nextItem) {
294→            return;
295→        }
296→
297→        this.playLive(nextItem);
298→    }
299→
300→    private handleRemoteControlCommand(command: {
301→        type:
302→            | 'channel-select-number'
303→            | 'volume-up'
304→            | 'volume-down'
305→            | 'volume-toggle-mute';
306→        number?: number;
307→    }): void {
308→        if (command.type !== 'channel-select-number' || !command.number) {
309→            return;
310→        }
311→
312→        const channels = this.xtreamStore.selectItemsFromSelectedCategory() as any[];
313→        const channel = getChannelItemByNumber(channels, command.number);
314→        if (!channel) {
315→            return;
316→        }
317→
318→        this.playLive(channel);
319→    }
320→}
