  1→import {
  2→    Component,
  3→    ElementRef,
  4→    EventEmitter,
  5→    inject,
  6→    Input,
  7→    OnChanges,
  8→    OnDestroy,
  9→    OnInit,
 10→    Output,
 11→    SimpleChanges,
 12→} from '@angular/core';
 13→import Artplayer from 'artplayer';
 14→import Hls from 'hls.js';
 15→import { Channel } from 'shared-interfaces';
 16→
 17→Artplayer.AUTO_PLAYBACK_TIMEOUT = 10000;
 18→
 19→@Component({
 20→    selector: 'app-art-player',
 21→    imports: [],
 22→    template: `<div #artplayer class="artplayer-container"></div>`,
 23→    styles: [
 24→        `
 25→            :host {
 26→                display: block;
 27→                width: 100%;
 28→                height: 100%;
 29→            }
 30→            .artplayer-container {
 31→                width: 100%;
 32→                height: 100%;
 33→            }
 34→        `,
 35→    ],
 36→})
 37→export class ArtPlayerComponent implements OnInit, OnDestroy, OnChanges {
 38→    @Input() channel!: Channel;
 39→    @Input() volume = 1;
 40→    @Input() showCaptions = false;
 41→    @Input() startTime = 0;
 42→    @Output() timeUpdate = new EventEmitter<{
 43→        currentTime: number;
 44→        duration: number;
 45→    }>();
 46→
 47→    private player!: Artplayer;
 48→    private hls: Hls | null = null;
 49→
 50→    private readonly elementRef = inject(ElementRef);
 51→
 52→    ngOnInit(): void {
 53→        this.initPlayer();
 54→    }
 55→
 56→    ngOnDestroy(): void {
 57→        this.destroyPlayer();
 58→    }
 59→
 60→    ngOnChanges(changes: SimpleChanges): void {
 61→        if (changes['channel'] && !changes['channel'].firstChange) {
 62→            this.destroyPlayer();
 63→            this.initPlayer();
 64→        }
 65→    }
 66→
 67→    private destroyPlayer(): void {
 68→        if (this.hls) {
 69→            this.hls.destroy();
 70→            this.hls = null;
 71→        }
 72→        if (this.player) {
 73→            this.player.destroy();
 74→        }
 75→    }
 76→
 77→    private initPlayer(): void {
 78→        const el = this.elementRef.nativeElement.querySelector(
 79→            '.artplayer-container'
 80→        );
 81→        const isLive = this.channel?.url?.toLowerCase().includes('m3u8');
 82→
 83→        this.player = new Artplayer({
 84→            container: el,
 85→            url: this.channel.url + (this.channel.epgParams || ''),
 86→            volume: this.volume,
 87→            isLive: isLive,
 88→            autoplay: true,
 89→            type: this.getVideoType(this.channel.url),
 90→            pip: true,
 91→            autoPlayback: true,
 92→            autoSize: true,
 93→            autoMini: true,
 94→            screenshot: true,
 95→            setting: true,
 96→            playbackRate: true,
 97→            aspectRatio: true,
 98→            fullscreen: true,
 99→            fullscreenWeb: true,
100→            playsInline: true,
101→            airplay: true,
102→            backdrop: true,
103→            mutex: true,
104→            theme: '#ff0000',
105→            customType: {
106→                m3u8: (video: HTMLVideoElement, url: string) => {
107→                    if (Hls.isSupported()) {
108→                        if (this.hls) {
109→                            this.hls.destroy();
110→                        }
111→                        this.hls = new Hls();
112→                        this.hls.loadSource(url);
113→                        this.hls.attachMedia(video);
114→                    } else if (
115→                        video.canPlayType('application/vnd.apple.mpegurl')
116→                    ) {
117→                        video.src = url;
118→                    }
119→                },
120→                mkv: function (video: HTMLVideoElement, url: string) {
121→                    video.src = url;
122→                    // Add error handling
123→                    video.onerror = () => {
124→                        console.error('Error loading MKV file:', video.error);
125→                        // Fallback to treating it as a regular video
126→                        video.src = url;
127→                    };
128→                },
129→            },
130→        });
131→
132→        if (this.startTime > 0) {
133→            this.player.on('ready', () => {
134→                this.player.seek = this.startTime;
135→            });
136→        }
137→
138→        this.player.on('video:timeupdate', () => {
139→            this.timeUpdate.emit({
140→                currentTime: this.player.currentTime,
141→                duration: this.player.duration,
142→            });
143→        });
144→    }
145→
146→    private getVideoType(url: string): string {
147→        const extension = url.split('.').pop()?.toLowerCase();
148→        switch (extension) {
149→            case 'mkv':
150→                return 'video/matroska'; // Changed from 'mkv'
151→            case 'm3u8':
152→                return 'm3u8';
153→            case 'mp4':
154→                return 'mp4';
155→            default:
156→                return 'auto';
157→        }
158→    }
159→}
