 31→} from 'components';
 32→import { PlaylistActions, ChannelActions, FavoritesActions } from 'm3u-state';
 33→import {
 34→    selectActive,
 35→    selectChannels,
 36→    selectCurrentEpgProgram,
 37→} from 'm3u-state';
 38→import {
 39→    Observable,
 40→    Subscription,
 41→    combineLatest,
 42→    combineLatestWith,
 43→    filter,
 44→    map,
 45→    startWith,
 46→    switchMap,
 47→    take,
 48→} from 'rxjs';
 49→import { DataService, PlaylistsService } from 'services';
 50→import {
 51→    Channel,
 52→    PLAYLIST_PARSE_BY_URL,
 53→    STORE_KEY,
 54→    Settings,
 55→    SidebarView,
 56→    VideoPlayer,
 57→} from 'shared-interfaces';
 58→import { SettingsStore } from '../../services/settings-store.service';
 59→import {
 60→    getAdjacentChannelItem,
 61→    getChannelItemByNumber,
 62→} from '../../shared/services/remote-channel-navigation.util';
 63→import { SettingsComponent } from '../../settings/settings.component';
 64→
 65→@Component({
 66→    imports: [
 67→        ArtPlayerComponent,
 68→        AsyncPipe,
 69→        AudioPlayerComponent,
 70→        CommonModule,
 71→        EpgListComponent,
 72→        HtmlVideoPlayerComponent,
 73→        InfoOverlayComponent,
 74→        MatSidenavModule,
 75→        ResizableDirective,
 76→        RouterLink,
 77→        SidebarComponent,
 78→        ToolbarComponent,
 79→        VjsPlayerComponent,
 80→    ],
 81→    templateUrl: './video-player.component.html',
 82→    styleUrl: './video-player.component.scss',
 83→})
 84→export class VideoPlayerComponent implements OnInit, OnDestroy {
 85→    private readonly activatedRoute = inject(ActivatedRoute);
 86→    private readonly dataService = inject(DataService);
 87→    private readonly dialog = inject(MatDialog);
 88→    private readonly overlay = inject(Overlay);
 89→    private readonly playlistsService = inject(PlaylistsService);
 90→    private readonly router = inject(Router);
 91→    private readonly settingsStore = inject(SettingsStore);
 92→    private readonly storage = inject(StorageMap);
 93→    private readonly store = inject(Store);
 94→
 95→    /** Active selected channel */
 96→    readonly activeChannel$ = this.store
 97→        .select(selectActive)
 98→        .pipe(filter((channel) => Boolean((channel as Channel)?.url)));
 99→
100→    /** Channels list */
101→    channels$!: Observable<Channel[]>;
102→
103→    /** Current epg program */
104→    readonly epgProgram$ = this.store.select(selectCurrentEpgProgram);
105→
106→    /** Selected video player options */
107→    playerSettings: Partial<Settings> = {
108→        player: VideoPlayer.VideoJs,
109→        showCaptions: false,
110→    };
111→
112→    readonly isDesktop = !!window['electron'];
113→
114→    sidebarView: SidebarView = 'CHANNELS';
115→
116→    /** EPG overlay reference */
117→    private overlayRef!: OverlayRef;
118→    private unsubscribeRemoteChannelChange?: () => void;
119→    private unsubscribeRemoteCommand?: () => void;
120→    private statusSubscription?: Subscription;
121→    private lastKnownVolume = 1;
122→
123→    /** Info overlay component reference for manual triggering */
124→    readonly infoOverlay = viewChild(InfoOverlayComponent);
125→
126→    /** Channel number input state */
127→    channelNumberInput = '';
128→    showChannelNumberOverlay = false;
129→    private channelNumberTimeout?: number;
130→
131→    volume = 1;
132→
133→    constructor() {
134→        // Initialize volume from localStorage in constructor
135→        const savedVolume = localStorage.getItem('volume');
136→        if (savedVolume !== null) {
137→            this.volume = Number(savedVolume);
138→        }
139→
140→        // React to settings changes
141→        effect(() => {
142→            this.playerSettings = {
143→                player: this.settingsStore.player(),
144→                showCaptions: this.settingsStore.showCaptions(),
145→            };
146→        });
147→    }
148→
149→    /**
150→     * Sets video player and subscribes to channel list from the store
151→     */
152→    ngOnInit(): void {
153→        this.applySettings();
154→        this.getPlaylistUrlAsParam();
155→
156→        // Setup remote control channel change listener (Electron only)
157→        if (this.isDesktop && window.electron?.onChannelChange) {
158→            const unsubscribe = window.electron.onChannelChange((data: {
159→                direction: 'up' | 'down';
160→            }) => {
161→                this.handleRemoteChannelChange(data.direction);
162→            });
163→            if (typeof unsubscribe === 'function') {
164→                this.unsubscribeRemoteChannelChange = unsubscribe;
165→            }
166→        }
167→        if (this.isDesktop && window.electron?.onRemoteControlCommand) {
168→            const unsubscribe = window.electron.onRemoteControlCommand(
169→                (command) => {
170→                    this.handleRemoteControlCommand(command);
171→                }
172→            );
173→            if (typeof unsubscribe === 'function') {
174→                this.unsubscribeRemoteCommand = unsubscribe;
175→            }
176→        }
177→
178→        this.channels$ = this.activatedRoute.params.pipe(
179→            combineLatestWith(this.activatedRoute.queryParams),
180→            switchMap(([params, queryParams]) => {
181→                if (params['id']) {
182→                    this.store.dispatch(
183→                        PlaylistActions.setActivePlaylist({
184→                            playlistId: params['id'],
185→                        })
186→                    );
187→                    return this.playlistsService.getPlaylist(params['id']).pipe(
188→                        map((playlist) => {
189→                            // Set user agent if specified on playlist level
190→                            if (playlist.userAgent) {
191→                                window.electron?.setUserAgent(
192→                                    playlist.userAgent,
193→                                    'localhost'
194→                                );
195→                            }
196→
197→                            this.store.dispatch(
198→                                ChannelActions.setChannels({
199→                                    channels: playlist.playlist.items,
200→                                })
201→                            );
202→
203→                            // Load favorites from the playlist
204→                            if (
205→                                playlist.favorites &&
206→                                playlist.favorites.length > 0
207→                            ) {
208→                                this.store.dispatch(
209→                                    FavoritesActions.setFavorites({
210→                                        channelIds: playlist.favorites,
211→                                    })
212→                                );
213→                            } else {
214→                                // Clear favorites if playlist has none
215→                                this.store.dispatch(
216→                                    FavoritesActions.setFavorites({
217→                                        channelIds: [],
218→                                    })
219→                                );
220→                            }
221→
222→                            return playlist.playlist.items as Channel[];
223→                        })
224→                    );
225→                } else if (queryParams['url']) {
226→                    return this.store.select(selectChannels) as Observable<
227→                        Channel[]
228→                    >;
229→                }
230→            })
231→        );
232→
233→        this.statusSubscription = combineLatest([
234→            this.channels$,
235→            this.activeChannel$,
236→            this.epgProgram$.pipe(startWith(null)),
237→        ]).subscribe(([channels, activeChannel, epgProgram]) => {
238→            if (!window.electron?.updateRemoteControlStatus || !activeChannel) {
239→                return;
240→            }
241→
242→            const currentIndex = channels.findIndex(
243→                (channel) => channel.url === activeChannel.url
244→            );
245→
246→            window.electron.updateRemoteControlStatus({
247→                portal: 'm3u',
248→                isLiveView: true,
249→                channelName:
250→                    activeChannel.name ??
251→                    activeChannel.tvg?.name,
252→                channelNumber: currentIndex >= 0 ? currentIndex + 1 : undefined,
253→                epgTitle: (epgProgram as any)?.title,
254→                epgStart: (epgProgram as any)?.start,
255→                epgEnd: (epgProgram as any)?.end,
256→                supportsVolume: true,
257→                volume: this.volume,
258→                muted: this.volume === 0,
259→            });
260→        });
261→    }
262→
263→    /**
264→     * Handle remote control channel change
265→     */
266→    handleRemoteChannelChange(direction: 'up' | 'down'): void {
267→        console.log(`Remote control: changing channel ${direction}`);
268→
269→        // Use combineLatest to get both values and take only the first emission
270→        combineLatest([this.channels$, this.activeChannel$])
271→            .pipe(
272→                filter(([channels, activeChannel]) => {
273→                    return channels.length > 0 && !!activeChannel;
274→                }),
275→                take(1),
276→                map(([channels, activeChannel]) => {
277→                    return {
278→                        channels,
279→                        activeChannel: activeChannel as Channel,
280→                    };
281→                })
282→            )
283→            .subscribe({
284→                next: ({ channels, activeChannel }) => {
285→                    const nextChannel = getAdjacentChannelItem(
286→                        channels,
287→                        activeChannel.url,
288→                        direction,
289→                        (channel) => channel.url
290→                    );
291→
292→                    if (!nextChannel) {
293→                        return;
294→                    }
295→
296→                    this.store.dispatch(
297→                        ChannelActions.setActiveChannel({
298→                            channel: nextChannel,
299→                        })
300→                    );
301→                },
302→                error: (err) => {
303→                    console.error('Error changing channel:', err);
304→                },
305→            });
306→    }
307→
308→    ngOnDestroy(): void {
309→        this.unsubscribeRemoteChannelChange?.();
310→        this.unsubscribeRemoteCommand?.();
311→        this.statusSubscription?.unsubscribe();
312→    }
313→
314→    /**
315→     * Opens a playlist provided as a url param
316→     * e.g. iptvnat.or?url=http://...
317→     * @pwaOnly
318→     */
319→    getPlaylistUrlAsParam() {
320→        const URL_REGEX = /^(http|https|file):\/\/[^ "]+$/;
321→        const playlistUrl = this.activatedRoute.snapshot.queryParams['url'];
322→
323→        if (playlistUrl && playlistUrl.match(URL_REGEX)) {
324→            this.dataService.sendIpcEvent(PLAYLIST_PARSE_BY_URL, {
325→                url: playlistUrl,
326→                isTemporary: true,
327→            });
328→        }
329→    }
330→
331→    /**
332→     * Reads the app configuration from the browsers storage and applies the settings in the current component
333→     */
334→    applySettings(): void {
335→        this.storage.get(STORE_KEY.Settings).subscribe((settings: unknown) => {
336→            if (settings && Object.keys(settings as Settings).length > 0) {
337→                this.playerSettings = {
338→                    player:
339→                        (settings as Settings).player || VideoPlayer.VideoJs,
340→                    showCaptions: (settings as Settings).showCaptions || false,
341→                };
342→            }
343→        });
344→    }
345→
346→    /**
347→     * Opens the overlay with multi EPG view
348→     */
349→    openMultiEpgView(): void {
350→        const positionStrategy = this.overlay
351→            .position()
352→            .global()
353→            .centerHorizontally()
354→            .centerVertically();
355→
356→        this.overlayRef = this.overlay.create({
357→            hasBackdrop: true,
358→            positionStrategy,
359→            width: '100%',
360→            height: '100%',
361→        });
362→
363→        const injector = Injector.create({
364→            providers: [
365→                {
366→                    provide: COMPONENT_OVERLAY_REF,
367→                    useValue: this.overlayRef,
368→                },
369→            ],
370→        });
371→
372→        const portal = new ComponentPortal(
373→            MultiEpgContainerComponent,
374→            null,
375→            injector
376→        );
377→
378→        const componentRef = this.overlayRef.attach(portal);
379→        componentRef.instance.playlistChannels = this.store.select(
380→            selectChannels
381→        ) as Observable<Channel[]>;
382→
383→        // Pass the active channel's tvg.id for highlighting
384→        this.activeChannel$.pipe(take(1)).subscribe((channel) => {
385→            if (channel) {
386→                componentRef.instance.activeChannelId = (channel as Channel).tvg?.id || null;
387→            }
388→        });
389→
390→        this.overlayRef.backdropClick().subscribe(() => {
391→            this.overlayRef.dispose();
392→        });
393→    }
394→
395→    openUrl(url: string) {
396→        window.open(url, '_blank');
397→    }
398→
399→    navigateHome() {
400→        this.router.navigate(['/']);
401→    }
402→
403→    openSettings() {
404→        this.dialog.open(SettingsComponent, {
405→            width: '1000px',
406→            height: '90%',
407→            data: { isDialog: true },
408→        });
409→    }
410→
411→    /**
412→     * Keyboard shortcut: Press 'I' to toggle EPG info overlay
413→     */
414→    @HostListener('document:keydown.i', ['$event'])
415→    handleInfoKeyPress(event: Event): void {
