                html: 'Audio',
                icon: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="22" height="22" fill="white">
                    <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/>
                </svg>`,
                width: 220,
                selector: tracks.map((track, index) => ({
                    html: track.name || track.lang || `Track ${index + 1}`,
                    default: track.id === this.hls?.audioTrack,
                })),
                onSelect: (_item, _el, _event) => {
                    const selectedIndex = tracks.findIndex(
                        (t) =>
                            (t.name || t.lang || `Track ${tracks.indexOf(t) + 1}`) ===
                            (_item as any).html
                    );
                    if (this.hls && selectedIndex >= 0) {
                        this.hls.audioTrack = selectedIndex;
                    }
                    return (_item as any).html;
                },
            };

            this.player.setting.update({
                ...audioSetting,
                name: 'audio-track',
            } as any);
        });
    }

    private getVideoType(url: string): string {
        const extension = url.split('.').pop()?.toLowerCase();
        switch (extension) {
            case 'mkv':
                return 'video/matroska';
            case 'm3u8':
                return 'm3u8';
            case 'mp4':
                return 'mp4';
            default:
                return 'auto';
        }
    }
}

