  8→    OnDestroy,
  9→    OnInit,
 10→    Output,
 11→    SimpleChanges,
 12→} from '@angular/core';
 13→import Artplayer from 'artplayer';
 14→import Hls from 'hls.js';
 15→import { Channel } from 'shared-interfaces';
 16→
 17→Artplayer.AUTO_PLAYBACK_TIMEOUT = 10000;
 18→
 19→@Component({
 20→    selector: 'app-art-player',
 21→    imports: [],
 22→    template: `<div #artplayer class="artplayer-container"></div>`,
 23→    styles: [
 24→        `
 25→            :host {
 26→                display: block;
 27→                width: 100%;
 28→                height: 100%;
 29→            }
 30→            .artplayer-container {
 31→                width: 100%;
 32→                height: 100%;
 33→            }
 34→        `,
 35→    ],
 36→})
 37→export class ArtPlayerComponent implements OnInit, OnDestroy, OnChanges {
 38→    @Input() channel!: Channel;
 39→    @Input() volume = 1;
 40→    @Input() showCaptions = false;
 41→    @Input() startTime = 0;
 42→    @Output() timeUpdate = new EventEmitter<{
 43→        currentTime: number;
 44→        duration: number;
 45→    }>();
 46→
 47→    private player!: Artplayer;
 48→    private hls: Hls | null = null;
 49→
 50→    private readonly elementRef = inject(ElementRef);
 51→
 52→    ngOnInit(): void {
 53→        this.initPlayer();
 54→    }
 55→
 56→    ngOnDestroy(): void {
 57→        this.destroyPlayer();
 58→    }
 59→
 60→    ngOnChanges(changes: SimpleChanges): void {
 61→        if (changes['channel'] && !changes['channel'].firstChange) {
 62→            this.destroyPlayer();
 63→            this.initPlayer();
 64→        }
 65→    }
 66→
 67→    private destroyPlayer(): void {
 68→        if (this.hls) {
 69→            this.hls.destroy();
 70→            this.hls = null;
 71→        }
 72→        if (this.player) {
 73→            this.player.destroy();
 74→        }
 75→    }
 76→
 77→    private initPlayer(): void {
 78→        const el = this.elementRef.nativeElement.querySelector(
 79→            '.artplayer-container'
 80→        );
 81→        const isLive = this.channel?.url?.toLowerCase().includes('m3u8');
 82→
 83→        this.player = new Artplayer({
 84→            container: el,
 85→            url: this.channel.url + (this.channel.epgParams || ''),
 86→            volume: this.volume,
 87→            isLive: isLive,
 88→            autoplay: true,
 89→            type: this.getVideoType(this.channel.url),
 90→            pip: true,
 91→            autoPlayback: true,
 92→            autoSize: true,
 93→            autoMini: true,
 94→            screenshot: true,
 95→            setting: true,
 96→            playbackRate: true,
 97→            aspectRatio: true,
 98→            fullscreen: true,
 99→            fullscreenWeb: true,
100→            playsInline: true,
101→            airplay: true,
102→            backdrop: true,
103→            mutex: true,
104→            theme: '#ff0000',
105→            customType: {
106→                m3u8: (video: HTMLVideoElement, url: string) => {
107→                    if (Hls.isSupported()) {
108→                        if (this.hls) {
109→                            this.hls.destroy();
110→                        }
111→                        this.hls = new Hls();
112→                        this.hls.loadSource(url);
113→                        this.hls.attachMedia(video);
114→                        this.setupHlsAudioTracks();
115→                    } else if (
116→                        video.canPlayType('application/vnd.apple.mpegurl')
117→                    ) {
118→                        video.src = url;
119→                    }
120→                },
121→                mkv: function (video: HTMLVideoElement, url: string) {
122→                    video.src = url;
123→                    video.onerror = () => {
124→                        console.error('Error loading MKV file:', video.error);
125→                        video.src = url;
126→                    };
127→                },
128→            },
129→        });
130→
131→        if (this.startTime > 0) {
132→            this.player.on('ready', () => {
133→                this.player.seek = this.startTime;
134→            });
135→        }
136→
137→        this.player.on('video:timeupdate', () => {
138→            this.timeUpdate.emit({
139→                currentTime: this.player.currentTime,
140→                duration: this.player.duration,
141→            });
142→        });
143→    }
144→
145→    /**
146→     * Listens for HLS.js audio tracks and adds a settings menu entry
147→     * to ArtPlayer for switching between available audio tracks.
148→     */
149→    private setupHlsAudioTracks(): void {
150→        if (!this.hls) return;
151→
152→        const hls = this.hls;
153→
154→        hls.on(Hls.Events.AUDIO_TRACKS_UPDATED, () => {
155→            const tracks = hls.audioTracks;
156→            if (!tracks || tracks.length <= 1) return;
157→
158→            this.player.setting.add({
159→                html: 'Audio',
160→                icon: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="22" height="22" fill="white">
161→                    <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/>
162→                </svg>`,
163→                width: 220,
164→                tooltip: tracks[hls.audioTrack]?.name || '',
165→                selector: tracks.map((track, index) => ({
166→                    html: track.name || track.lang || `Track ${index + 1}`,
167→                    default: index === hls.audioTrack,
168→                })),
169→                onSelect: function (this: Artplayer, item: any) {
170→                    const selectedIndex = tracks.findIndex(
171→                        (t, i) =>
172→                            (t.name || t.lang || `Track ${i + 1}`) === item.html
173→                    );
174→                    if (selectedIndex >= 0) {
175→                        hls.audioTrack = selectedIndex;
176→                    }
177→                    return item.html;
178→                },
