import {
    Component,
    ElementRef,
    EventEmitter,
    Input,
    OnChanges,
    OnDestroy,
    OnInit,
    Output,
    SimpleChanges,
    ViewChild,
    ViewEncapsulation,
} from '@angular/core';
import '@yangkghjh/videojs-aspect-ratio-panel';
import videoJs from 'video.js';
import 'videojs-contrib-quality-levels';
import 'videojs-quality-selector-hls';

/**
 * This component contains the implementation of video player that is based on video.js library
 */
@Component({
    selector: 'app-vjs-player',
    templateUrl: './vjs-player.component.html',
    styleUrls: ['./vjs-player.component.scss'],
    encapsulation: ViewEncapsulation.None,
    standalone: true,
})
export class VjsPlayerComponent implements OnInit, OnChanges, OnDestroy {
    /** DOM-element reference */
    @ViewChild('target', { static: true }) target!: ElementRef<Element>;
    /** Options of VideoJs player */
    @Input() options!: any;
    /** VideoJs object */
    player!: any;
    @Input() volume = 1;
    @Input() startTime = 0;
    @Output() timeUpdate = new EventEmitter<{
        currentTime: number;
        duration: number;
    }>();

    /** Audio track menu button reference */
    private audioTrackButton: any;

    /**
     * Instantiate Video.js on component init
     */
    ngOnInit(): void {
        this.player = videoJs(
            this.target.nativeElement,
            {
                ...this.options,
                autoplay: true,
            },
            () => {
                console.log(
                    'Setting VideoJS player initial volume to:',
                    this.volume
                );
                this.player.volume(this.volume);

                this.player.on('loadedmetadata', () => {
                    if (this.startTime > 0) {
                        this.player.currentTime(this.startTime);
                    }
                    this.setupAudioTrackMenu();
                });

                this.player.on('volumechange', () => {
                    const currentVolume = this.player.volume();
                    localStorage.setItem('volume', currentVolume.toString());
                });

                this.player.on('timeupdate', () => {
                    this.timeUpdate.emit({
                        currentTime: this.player.currentTime(),
                        duration: this.player.duration(),
                    });
                });
            }
        );
        try {
            if (typeof this.player.qualitySelectorHls === 'function') {
                this.player.qualitySelectorHls({
                    displayCurrentQuality: true,
                });
            }
        } catch (e) {
            console.warn('qualitySelectorHls plugin failed to initialize:', e);
        }
        try {
            if (typeof this.player['aspectRatioPanel'] === 'function') {
                this.player['aspectRatioPanel']();
            }
        } catch (e) {
            console.warn('aspectRatioPanel plugin failed to initialize:', e);
        }
    }

    /**
     * Replaces the url source of the player with the changed source url
     * @param changes contains changed channel object
     */
    ngOnChanges(changes: SimpleChanges): void {
        if (changes['options'].previousValue) {
            this.player.src(changes['options'].currentValue.sources[0]);
            this.removeAudioTrackButton();
        }
        if (changes['volume']?.currentValue !== undefined && this.player) {
            console.log(
                'Setting VideoJS player volume to:',
                changes['volume'].currentValue
            );
            this.player.volume(changes['volume'].currentValue);
        }
    }

    /**
     * Removes the players HTML reference on destroy
     */
    ngOnDestroy(): void {
        if (this.player) {
            this.player.dispose();
        }
    }

    /**
     * Sets up the audio track selection menu in the control bar.
     * Uses the Video.js audioTracks() API which works with both
     * native multi-audio streams and HLS.js alternate audio tracks.
     */
    private setupAudioTrackMenu(): void {
        this.removeAudioTrackButton();

        const audioTracks = this.player.audioTracks();
        if (!audioTracks || audioTracks.length <= 1) {
            return;
        }

        const MenuButton = videoJs.getComponent('MenuButton') as any;
        const MenuItem = videoJs.getComponent('MenuItem') as any;
        const player = this.player;

        class AudioTrackMenuButton extends MenuButton {
            constructor(p: any, options: Record<string, unknown> = {}) {
                super(p, options);
                this.controlText('Audio');

                const tracks = p.audioTracks();
                const updateHandler = () => this.update();
                tracks.addEventListener('change', updateHandler);
                tracks.addEventListener('addtrack', updateHandler);
                tracks.addEventListener('removetrack', updateHandler);

                this.on('dispose', () => {
                    tracks.removeEventListener('change', updateHandler);
                    tracks.removeEventListener('addtrack', updateHandler);
                    tracks.removeEventListener('removetrack', updateHandler);
                });
            }

            createEl() {
                const el = super.createEl();
                const icon = document.createElement('span');
                icon.className = 'vjs-audio-track-icon';
                icon.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="16" height="16" fill="white">
                    <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/>
                </svg>`;
                el.insertBefore(icon, el.firstChild);
                return el;
            }

            createItems() {
                const items: any[] = [];
                const tracks = player.audioTracks();

                for (let i = 0; i < tracks.length; i++) {
                    const track = tracks[i];
                    const label =
                        track.label || track.language || `Track ${i + 1}`;

                    const item = new MenuItem(player, {
                        label,
                        selectable: true,
                        multiSelectable: false,
                    });

                    item.selected(track.enabled);

                    ((menuItem: any, trackIndex: number) => {
                        menuItem.on('click', () => {
                            const allTracks = player.audioTracks();
                            for (let j = 0; j < allTracks.length; j++) {
                                allTracks[j].enabled = j === trackIndex;
                            }
                        });
                    })(item, i);

                    items.push(item);
                }
                return items;
            }
        }

        videoJs.registerComponent(
            'AudioTrackButton',
            AudioTrackMenuButton as any
        );
        this.audioTrackButton = player
            .getChild('controlBar')
            .addChild('AudioTrackButton', {});
    }

    private removeAudioTrackButton(): void {
        if (this.audioTrackButton) {
            this.player
                .getChild('controlBar')
                ?.removeChild(this.audioTrackButton);
            this.audioTrackButton = null;
        }
    }
}

